#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

int main() {
  int n;
  cin >> n;
  vector<int> arr(n);
  for (int I = 0; I < n; ++i) {
    cin >> arr[i];
  }
  sort(arr.begin(), arr.end());
  int count = 1;
  int max_count = 1;
  int max_element = arr[0];
  for (int I = 1; I < n; ++i) {
    if (arr[i] == arr[i-1]) {
      count++;
    } else {
      count = 1;
    }
    if (count > max_count) {
      max_count = count;
      max_element = arr[i];
    }
  }
  cout << "The most occurring element is " << max_element << endl;
  cout << "The second most occurring element is " << arr[n-1] << endl;
  return 0;
}
```

This program first sorts the array in ascending order using the `sort` function. Then, it iterates through the array and keeps track of the current element and the count of the number of times it appears in the array. If the current element is the same as the previous element, the count is incremented. Otherwise, the count is reset to 1. If the count is greater than the maximum count seen so far, the maximum count and the maximum element are updated. Finally, the program outputs the two most occurring elements in the array.<|end_of_text|>

